use super::*;
use super::remote::{Collection,Subject,Label,User};
use std::{sync::{Arc,Mutex},collections::BTreeMap};
use axum::{Router,routing::{get,post,patch},extract::Path,http::StatusCode};
use tower::ServiceExt;
fn subject(id:i64)->Subject{Subject{id:format!("v{id}"),title:format!("Game {id}"),description:Some("A game".into()),image:Some(json!({"url":"https://t.vndb.org/cv/01/1.jpg"})),released:Some("2020-01-01".into())}}
fn collection(id:i64,status:i64,vote:Option<i64>)->Collection{Collection{id:format!("v{id}"),vote,labels:vec![Label{id:status},Label{id:6},Label{id:20}],vn:subject(id)}}
fn fixture()->(tempfile::TempDir,App,Account){let t=tempfile::tempdir().unwrap();let a=crate::initialize(t.path().join("state")).unwrap();let account=Account{user:User{id:"u9".into(),username:"fixture".into(),permissions:vec!["listread".into(),"listwrite".into()]},credential:"generated-secret-reference".into(),mode:"full".into(),automatic:false,initialized:true,last_sync:None,preview:"preview".into(),error:String::new(),results:vec![]};store::save_account(&a.db.lock().unwrap(),&account).unwrap();(t,a,account)}
fn linked(a:&App,status:&str,rating:i64,base_status:Option<i64>,base_rating:Option<i64>){let c=a.db.lock().unwrap();c.execute("INSERT INTO works(id,title,original_title,vndb_id,status,personal_rating,notes) VALUES('w','Game','Game','v1',?1,nullif(?2,0),'Private note')",params![status,rating]).unwrap();c.execute("INSERT INTO vndb_sync_links(work_id,subject_id,base_status,base_rating) VALUES('w',1,?1,?2)",params![base_status,base_rating]).unwrap();}
fn choice(a:&App,id:i64,field:&str,action:&str)->Choice{let row=store::rows(&a.db.lock().unwrap(),"full").unwrap().into_iter().find(|r|r.subject_id==id&&r.field==field).unwrap();Choice{subject_id:id,field:field.into(),fingerprint:row.fingerprint,action:action.into(),work_id:None}}
fn work(a:&App)->Value{crate::work_catalog::one(&a.db.lock().unwrap(),"w").unwrap().unwrap()}
#[derive(Clone,Default)]struct Mock{items:Arc<Mutex<BTreeMap<i64,Collection>>>,writes:Arc<Mutex<Vec<Value>>>,fail:Arc<Mutex<bool>>,edit:Arc<Mutex<Option<crate::db::Db>>>}
impl Mock{fn new(rows:Vec<Collection>)->Self{Self{items:Arc::new(Mutex::new(rows.into_iter().map(|r|(subject_id(&r.id).unwrap(),r)).collect())),..Default::default()}}}
async fn list(State(m):State<Mock>,h:HeaderMap,Json(body):Json<Value>)->Json<Value>{assert_eq!(h["authorization"],"Token generated-token");assert_eq!(body["user"],"u9");let rows=m.items.lock().unwrap();let filter=&body["filters"];let id=filter.get(2).and_then(Value::as_str).map(|id|subject_id(id).unwrap());let found:Vec<_>=rows.iter().filter(|(k,_)|match id{None=>true,Some(id)=>if filter[1]=="="{**k==id}else{**k>id}}).map(|(_,v)|v.clone()).collect();Json(json!({"more":found.len()>100,"results":found.into_iter().take(100).collect::<Vec<_>>()}))}
async fn set(State(m):State<Mock>,Path(id):Path<String>,Json(body):Json<Value>)->StatusCode{if *m.fail.lock().unwrap(){return StatusCode::SERVICE_UNAVAILABLE;}let id=subject_id(&id).unwrap();m.writes.lock().unwrap().push(body.clone());{let mut items=m.items.lock().unwrap();let row=items.entry(id).or_insert_with(||Collection{labels:vec![],..collection(id,1,None)});if let Some(vote)=body.get("vote"){row.vote=vote.as_i64();}if let Some(remove)=body["labels_unset"].as_array(){row.labels.retain(|l|!remove.contains(&json!(l.id)));}if let Some(add)=body["labels_set"].as_array(){for id in add{let id=id.as_i64().unwrap();if !row.labels.iter().any(|l|l.id==id){row.labels.push(Label{id});}}}}
 if let Some(db)=m.edit.lock().unwrap().take(){db.lock().unwrap().execute("UPDATE works SET personal_rating=93,revision=revision+1 WHERE id='w'",[]).unwrap();}StatusCode::NO_CONTENT}
async fn server(mock:Mock)->(remote::Client,tokio::task::JoinHandle<()>){let router=Router::new().route("/ulist",post(list)).route("/ulist/{id}",patch(set)).route("/vn",post(|Json(body):Json<Value>|async move{let id=subject_id(body["filters"][2].as_str().unwrap()).unwrap();Json(json!({"results":[subject(id)],"more":false}))})).with_state(mock);let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let task=tokio::spawn(async move{axum::serve(listener,router).await.unwrap();});(remote::Client::at("generated-token".into(),base).unwrap(),task)}
#[test]fn label_mapping_and_patch_preserve_orthogonal_fields(){for id in 1..=5{assert_eq!(store::remote_status(store::local_status(id).unwrap()).unwrap(),id);}let mut row=collection(1,1,Some(85));row.labels.push(Label{id:5});assert_eq!(row.status(),1);row.labels.push(Label{id:2});assert_eq!(row.status(),-1);row.labels.retain(|l|l.id>4);assert_eq!(row.status(),5);row.labels.retain(|l|l.id!=5);assert_eq!(row.status(),0);assert_eq!(remote::patch("rating",0).unwrap(),json!({"vote":null}));assert_eq!(remote::patch("status",2).unwrap(),json!({"labels_set":[2],"labels_unset":[1,3,4]}));assert!(remote::patch("rating",9).is_err());assert!(remote::patch("rating",101).is_err());assert!(subject_id("https://vndb.org/v17").is_ok());assert!(subject_id("https://evil.example/v17").is_err());}
#[tokio::test]async fn simultaneous_status_push_and_rating_pull_are_independent(){let(_t,a,_)=fixture();linked(&a,"completed",80,Some(1),Some(80));let m=Mock::new(vec![collection(1,1,Some(91))]);let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert_eq!(work(&a)["status"],"completed");assert_eq!(work(&a)["personal_rating"],91);assert_eq!(m.writes.lock().unwrap().as_slice(),&[json!({"labels_set":[2],"labels_unset":[1,3,4]})]);let row=m.items.lock().unwrap()[&1].clone();assert_eq!(row.vote,Some(91));assert!(row.labels.iter().any(|l|l.id==6)&&row.labels.iter().any(|l|l.id==20));task.abort();}
#[tokio::test]async fn rating_push_clear_and_remote_clear_round_trip(){let(_t,a,_)=fixture();linked(&a,"playing",87,Some(1),Some(80));let m=Mock::new(vec![collection(1,1,Some(80))]);let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert_eq!(m.items.lock().unwrap()[&1].vote,Some(87));m.items.lock().unwrap().get_mut(&1).unwrap().vote=None;sync_client(&a,&client).await.unwrap();assert!(work(&a)["personal_rating"].is_null());a.db.lock().unwrap().execute("UPDATE works SET personal_rating=77 WHERE id='w'",[]).unwrap();sync_client(&a,&client).await.unwrap();a.db.lock().unwrap().execute("UPDATE works SET personal_rating=NULL WHERE id='w'",[]).unwrap();sync_client(&a,&client).await.unwrap();assert_eq!(m.writes.lock().unwrap().last().unwrap(),&json!({"vote":null}));task.abort();}
#[tokio::test]async fn conflicts_are_explicit_per_field_and_stale_values_rejected(){let(_t,a,mut account)=fixture();linked(&a,"completed",90,Some(1),Some(80));let m=Mock::new(vec![collection(1,3,Some(85))]);let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert!(m.writes.lock().unwrap().is_empty());assert!(state(&a).unwrap()["rows"].as_array().unwrap().iter().all(|r|r["kind"]=="conflict"));let inputs=[choice(&a,1,"status","remote"),choice(&a,1,"rating","local")];let result=apply_choices(&a,&mut account,&client,&inputs).await.unwrap();assert!(result.iter().all(|r|r["ok"]==true));assert_eq!(work(&a)["status"],"on_hold");assert_eq!(m.items.lock().unwrap()[&1].vote,Some(90));let old=choice(&a,1,"rating","local");a.db.lock().unwrap().execute("UPDATE works SET personal_rating=95 WHERE id='w'",[]).unwrap();assert!(apply_choice(&a,&account,&client,&old).await.is_err());let current=choice(&a,1,"rating","local");m.items.lock().unwrap().get_mut(&1).unwrap().vote=Some(75);assert!(apply_choice(&a,&account,&client,&current).await.is_err());task.abort();}
#[tokio::test]async fn missing_entries_initial_conflicts_and_ambiguous_labels_do_not_auto_push(){let(_t,a,_)=fixture();linked(&a,"playing",80,None,None);let m=Mock::new(vec![collection(1,2,Some(90))]);let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert!(m.writes.lock().unwrap().is_empty());m.items.lock().unwrap().get_mut(&1).unwrap().labels.push(Label{id:3});sync_client(&a,&client).await.unwrap();assert_eq!(state(&a).unwrap()["rows"][0]["kind"],"unsupported");m.items.lock().unwrap().clear();sync_client(&a,&client).await.unwrap();assert!(m.writes.lock().unwrap().is_empty());assert_eq!(work(&a)["personal_rating"],80);apply_choice(&a,&connected(&a).unwrap(),&client,&choice(&a,1,"rating","local")).await.unwrap();assert_eq!(m.items.lock().unwrap()[&1].vote,Some(80));assert_eq!(state(&a).unwrap()["rows"][0]["kind"],"unsupported");task.abort();}
#[tokio::test]async fn failed_writes_retry_and_edits_during_http_remain_pending(){let(_t,a,_)=fixture();linked(&a,"playing",90,Some(1),Some(80));let m=Mock::new(vec![collection(1,1,Some(80))]);*m.fail.lock().unwrap()=true;let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert_eq!(state(&a).unwrap()["rows"][1]["base"],80);assert!(!connected(&a).unwrap().error.is_empty());*m.fail.lock().unwrap()=false;*m.edit.lock().unwrap()=Some(a.db.clone());sync_client(&a,&client).await.unwrap();assert_eq!(work(&a)["personal_rating"],93);assert_eq!(state(&a).unwrap()["rows"][1]["base"],90);assert_eq!(state(&a).unwrap()["rows"][1]["kind"],"push");sync_client(&a,&client).await.unwrap();assert_eq!(m.items.lock().unwrap()[&1].vote,Some(93));task.abort();}
#[test]fn import_without_resources_exact_identity_matching_and_hide(){let(_t,a,_)=fixture();let c=a.db.lock().unwrap();store::replace_remote(&c,&[collection(1,2,Some(88))]).unwrap();let id=store::import(&c,1).unwrap();let w=crate::work_catalog::one(&c,&id).unwrap().unwrap();assert_eq!(w["personal_rating"],88);assert_eq!(w["resources"],0);assert_eq!(w["vndb_id"],"v1");assert_eq!(w["status"],"completed");c.execute("UPDATE vndb_sync_links SET hidden=1 WHERE work_id=?1",[&id]).unwrap();assert!(crate::work_catalog::all(&c).unwrap().is_empty());assert!(automatic_choices(store::rows(&c,"full").unwrap()).is_empty());c.execute("DELETE FROM vndb_sync_links",[]).unwrap();assert_eq!(store::rows(&c,"full").unwrap()[0].kind,"match");assert!(store::import(&c,1).is_err());}
#[tokio::test]async fn import_pagination_and_ignored_state_survive_restart(){let(t,a,mut account)=fixture();let m=Mock::new((1..=103).map(|id|collection(id,1,Some(80))).collect());let(client,task)=server(m).await;fetch(&a,&mut account,&client).await.unwrap();assert_eq!(state(&a).unwrap()["rows"].as_array().unwrap().len(),103);apply_choice(&a,&account,&client,&choice(&a,1,"entry","skip")).await.unwrap();apply_choice(&a,&account,&client,&choice(&a,2,"entry","import")).await.unwrap();let path=a.state_dir.clone();drop(a);let a=crate::initialize(path).unwrap();let c=a.db.lock().unwrap();assert_eq!(store::rows(&c,"full").unwrap().iter().find(|r|r.subject_id==1).unwrap().kind,"ignored");assert_eq!(crate::work_catalog::all(&c).unwrap().len(),1);drop(c);task.abort();drop(t);}
#[test]fn backup_and_schema_upgrade_keep_rating_without_account_credentials(){let(t,a,_)=fixture();linked(&a,"completed",87,Some(2),Some(87));let backup=crate::backup::export(&a.db,t.path()).unwrap();let c=rusqlite::Connection::open(backup.join("collection.sqlite")).unwrap();assert!(store::account(&c).unwrap().is_none());assert_eq!(crate::work_catalog::one(&c,"w").unwrap().unwrap()["personal_rating"],87);assert!(!state(&a).unwrap().to_string().contains("generated-secret-reference"));let path=a.state_dir.join("library.sqlite");drop(a);{let c=rusqlite::Connection::open(&path).unwrap();c.execute_batch("DROP TABLE vndb_sync_links;DROP TABLE vndb_sync_remote;DROP TABLE vndb_sync_ignored;DROP TRIGGER catalog_changed_works_UPDATE;ALTER TABLE works DROP COLUMN personal_rating;PRAGMA user_version=49;").unwrap();}let db=crate::db::open(&path).unwrap();let c=db.lock().unwrap();assert_eq!(crate::work_catalog::all(&c).unwrap().len(),1);assert_eq!(c.query_row("PRAGMA user_version",[],|r|r.get::<_,i64>(0)).unwrap(),50);}
#[tokio::test]async fn token_permissions_auth_failures_and_rating_revision_validation(){for (code,permissions)in[(200,vec!["listread"]),(401,vec![]),(429,vec![]),(302,vec![])]{let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let task=tokio::spawn(async move{axum::serve(listener,Router::new().route("/authinfo",get(move||{let p=permissions.clone();async move{(StatusCode::from_u16(code).unwrap(),Json(json!({"id":"u9","username":"fixture","permissions":p})))}}))).await.unwrap();});assert!(remote::Client::at("secret".into(),base).unwrap().me().await.is_err());task.abort();}let(_t,a,_)=fixture();linked(&a,"playing",0,None,None);let mut h=HeaderMap::new();h.insert("authorization",format!("Bearer {}",a.token).parse().unwrap());let _ = rating(State(a.clone()),h.clone(),Json(Rating{work_id:"w".into(),revision:1,rating:Some(87)})).await.map_err(|e|e.0).unwrap();assert!(rating(State(a.clone()),h,Json(Rating{work_id:"w".into(),revision:1,rating:None})).await.is_err());let response=crate::router(a).oneshot(axum::http::Request::builder().uri("/api/vndb_sync").header("host","127.0.0.1").body(axum::body::Body::empty()).unwrap()).await.unwrap();assert_eq!(response.status(),401);}
#[test]fn merging_a_resource_card_preserves_sync_identity_and_rating(){let(_t,a,_)=fixture();linked(&a,"completed",91,Some(2),Some(91));a.db.lock().unwrap().execute_batch("INSERT INTO works(id,title,original_title) VALUES('target','Game','Game');").unwrap();crate::grouping::merge(&a.db,"w","target",1,1).unwrap();let c=a.db.lock().unwrap();let w=crate::work_catalog::one(&c,"target").unwrap().unwrap();assert_eq!(w["vndb_sync_id"],1);assert_eq!(w["personal_rating"],91);assert_eq!(w["status"],"completed");}

#[tokio::test]async fn background_apply_outlives_request_and_exposes_completion(){
 let(_t,a,account)=fixture();linked(&a,"completed",90,Some(1),Some(80));let m=Mock::new(vec![collection(1,1,Some(80))]);let(client,task)=server(m.clone()).await;store::replace_remote(&a.db.lock().unwrap(),&[collection(1,1,Some(80))]).unwrap();
 let inputs=vec![choice(&a,1,"status","local"),choice(&a,1,"rating","local")];let gate=a.vndb_sync_gate.clone().try_lock_owned().unwrap();background(a.clone(),account,client,gate,Some(inputs));assert_eq!(state(&a).unwrap()["running"],true);assert!(a.vndb_sync_gate.try_lock().is_err());
 tokio::time::timeout(std::time::Duration::from_secs(5),async{loop{if state(&a).unwrap()["running"]==false{break;}tokio::task::yield_now().await;}}).await.unwrap();let done=state(&a).unwrap();assert_eq!(done["results"].as_array().unwrap().len(),2);assert!(done["results"].as_array().unwrap().iter().all(|r|r["ok"]==true));assert_eq!(m.items.lock().unwrap()[&1].vote,Some(90));task.abort();
}
#[tokio::test]async fn opposite_directions_and_ambiguous_status_do_not_block_rating(){
 let(_t,a,_)=fixture();linked(&a,"playing",90,Some(1),Some(80));let mut entry=collection(1,3,Some(80));entry.labels.push(Label{id:5});let m=Mock::new(vec![entry]);let(client,task)=server(m.clone()).await;sync_client(&a,&client).await.unwrap();assert_eq!(work(&a)["status"],"on_hold");assert_eq!(m.items.lock().unwrap()[&1].vote,Some(90));assert!(m.items.lock().unwrap()[&1].labels.iter().any(|l|l.id==5));
 {let mut items=m.items.lock().unwrap();let row=items.get_mut(&1).unwrap();row.labels.push(Label{id:2});row.vote=Some(94);}sync_client(&a,&client).await.unwrap();assert_eq!(work(&a)["status"],"on_hold");assert_eq!(work(&a)["personal_rating"],94);assert_eq!(state(&a).unwrap()["rows"][0]["kind"],"unsupported");task.abort();
}

#[tokio::test]async fn stopping_services_cancels_manual_sync_and_releases_the_gate(){
 let(_t,a,account)=fixture();let(client,task)=server(Mock::default()).await;let worker=start(a.clone());let gate=a.vndb_sync_gate.clone().try_lock_owned().unwrap();background(a.clone(),account,client,gate,None);worker.request_stop();
 tokio::time::timeout(std::time::Duration::from_secs(5),async{loop{if a.vndb_sync_gate.try_lock().is_ok(){break;}tokio::task::yield_now().await;}}).await.unwrap();task.abort();
}
